import {defaults,initialState,advance,metrics,G} from './physics.js?v=responsive-4';
import {LabScene} from './scene.js?v=responsive-4';
const $=id=>document.getElementById(id);
const configs={
 pulley:{name:'POLEA Y ROCA',fields:[['mass','Masa',20,250,5,'kg'],['height','Elevación',2,7,.5,'m'],['duration','Tiempo',4,20,1,'s']],equations:[['Trabajo','W = mgh'],['Fuerza','F = mg / n'],['Cuerda','d = n · h'],['Potencia','P = mgh / t']],assumptions:'Poleas ideales y elevación a rapidez constante. La altura se mide desde la posición inicial de la roca.'},
 track:{name:'PISTA',fields:[['mass','Masa',20,120,5,'kg'],['height','Altura inicial',3,12,.5,'m'],['mu','Rozamiento',0,.30,.01,'μ']],equations:[['Cinética','K = ½mv²'],['Potencial','U = mgh'],['Balance','K + U + E<sub>dis</sub> = E<sub>inicial</sub>'],['Normal','N = mg cos θ']],assumptions:'Carrito guiado, sin energía de rotación de las ruedas. Regresa por gravedad y el rozamiento reduce su energía mecánica.'},
 rocket:{name:'COHETE',fields:[['mass','Masa',20,150,5,'kg'],['thrust','Empuje',50,1000,25,'N'],['burn','Encendido',1,8,.5,'s'],['mu','Rozamiento',0,.4,.01,'μ']],equations:[['Trabajo neto','W<sub>neto</sub> = ΔK'],['Empuje','W = F · Δx<sub>encendido</sub>'],['Rozamiento','W<sub>r</sub> = −μmgx'],['Potencia','P = Fv']],assumptions:'Masa y empuje constantes. La carretera continúa; la medición termina al detenerse o a los 30 s.'}
};
let mode='pulley',params={...defaults.pulley},state=initialState(mode,params),playing=false,speed=1,history=[],lastSample=-1,sampleInterval=.1,lastUI=0,accumulator=0,previous=performance.now(),toastTimer,approachTime=0;
const approachDuration=1.8;
const fmt=(n,d=0)=>Number(n).toLocaleString('es-GT',{minimumFractionDigits:d,maximumFractionDigits:d});
const setValue=(id,n,unit,d=0)=>$(id).innerHTML=`${fmt(n,d)} <small>${unit}</small>`;
$('play').disabled=true;
const scene=new LabScene($('scene-mount'),()=>{$('loading').hidden=true;$('play').disabled=false;scene.update(state,params);},error=>{console.error('Escena 3D:',error);$('play').disabled=false;$('loading').classList.add('error');$('loading-text').textContent='No se pudo cargar la vista 3D. Recarga la página.';});
function sample(force=false){if(force||state.t-lastSample>=sampleInterval-1e-8){history.push({...state,...metrics(state,params)});lastSample=state.t;if(history.length>7200){history=history.filter((_,i)=>i%2===0||i===history.length-1);sampleInterval*=2;}}}
function reset(){playing=false;accumulator=0;approachTime=0;state=initialState(mode,params);history=[];lastSample=-1;sampleInterval=.1;sample(true);scene.rebuild(mode,params);scene.update(state,params,{approach:mode==='pulley'?0:1,motionTime:0});updateUI();drawChart();}
function fields(){
 $('parameters').innerHTML='';
 if(mode==='pulley'){const field=document.createElement('div');field.className='parameter';field.innerHTML='<div class="parameter-heading"><label for="param-ratio">Polea</label></div><select id="param-ratio"><option value="1">Fija</option><option value="2">Móvil · 2 tramos</option></select>'; $('parameters').appendChild(field);$('param-ratio').value=String(params.ratio);$('param-ratio').addEventListener('change',e=>{params.ratio=Number(e.target.value);reset();});}
 for(const[key,label,min,max,step,unit]of configs[mode].fields){
  const field=document.createElement('div');field.className='parameter';const decimals=step<1?(key==='mu'?2:1):0;
  field.innerHTML=`<div class="parameter-heading"><label for="param-${key}">${label}</label><span class="number-field"><input id="value-${key}" type="number" inputmode="decimal" aria-label="${label}" min="${min}" max="${max}" step="${step}" value="${params[key].toFixed(decimals)}"><small>${unit==='μ'?'':unit}</small></span></div><input type="range" id="param-${key}" aria-label="${label}" min="${min}" max="${max}" step="${step}" value="${params[key]}"><div class="range-ends"><span>${fmt(min,decimals)}</span><span>${fmt(max,decimals)}</span></div>`;
  $('parameters').appendChild(field);
  const applyValue=raw=>{let value=Number(raw);if(raw===''||!Number.isFinite(value)){ $('value-'+key).value=params[key].toFixed(decimals);return;}value=Math.max(min,Math.min(max,value));value=Number((min+Math.round((value-min)/step)*step).toFixed(decimals));params[key]=value;$('param-'+key).value=String(value);$('value-'+key).value=value.toFixed(decimals);reset();};
  $('param-'+key).addEventListener('input',e=>applyValue(e.target.value));$('value-'+key).addEventListener('change',e=>applyValue(e.target.value));$('value-'+key).addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();applyValue(e.target.value);e.target.blur();}});
 }
}
function choose(next){mode=next;params={...defaults[mode]};const conf=configs[mode];document.querySelectorAll('.scenario-tab').forEach(button=>{const active=button.dataset.mode===mode;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active));});$('experiment').setAttribute('aria-labelledby','tab-'+mode);$('scene-name').textContent=conf.name;$('assumptions').textContent=conf.assumptions;$('equations').innerHTML=conf.equations.map(([label,equation])=>`<div class="equation"><span>${label}</span><b>${equation}</b></div>`).join('');fields();reset();}
function updateUI(){
 const m=metrics(state,params);$('time').textContent=fmt(state.t,2);$('status').textContent=state.status;$('play-label').textContent=playing?'Pausar':state.finished?'Repetir':state.t>0?'Continuar':'Iniciar';$('play-icon').textContent=playing?'Ⅱ':'▶';
 if(mode==='pulley'){$('readout-a-label').textContent='Elevación';setValue('readout-a',state.h,'m',2);$('readout-b-label').textContent='Fuerza';setValue('readout-b',m.tension,'N');$('readout-c-label').textContent='Trabajo';setValue('readout-c',m.input,'J');$('balance-label').textContent='Cuerda · potencia';$('balance-value').textContent=`${fmt(m.rope,2)} m · ${fmt(params.mass*G*params.height/params.duration)} W`;}
 else if(mode==='track'){$('readout-a-label').textContent='Altura';setValue('readout-a',state.h,'m',2);$('readout-b-label').textContent='Rapidez';setValue('readout-b',Math.abs(state.v),'m/s',2);$('readout-c-label').textContent='Rozamiento';setValue('readout-c',-m.loss,'J');$('balance-label').textContent='Energía total';$('balance-value').textContent=`${fmt(m.K+m.U+m.loss)} J`;}
 else{$('readout-a-label').textContent='Distancia';setValue('readout-a',state.x,'m',2);$('readout-b-label').textContent='Rapidez';setValue('readout-b',state.v,'m/s',2);$('readout-c-label').textContent='Trabajo neto';setValue('readout-c',m.workNet,'J');$('balance-label').textContent='Trabajo del cohete';$('balance-value').textContent=`${fmt(m.input)} J`;}
 const denominator=mode==='pulley'?params.mass*G*params.height+m.initial:Math.max(1,m.initial+m.input);
 for(const[key,val]of [['k',m.K],['u',m.U],['d',m.loss]]){$('energy-'+key).textContent=fmt(val)+' J';$('bar-'+key).style.width=(Math.max(0,Math.min(100,val/denominator*100)))+'%';}
 $('chart-detail').textContent=`${history.length} muestras`;
 document.querySelectorAll('[data-force]').forEach(el=>{el.hidden=(el.dataset.force==='friction'&&(mode==='pulley'||params.mu===0))||(el.dataset.force==='thrust'&&mode!=='rocket');});
}
function drawChart(){
 const canvas=$('chart'),w=canvas.clientWidth,h=canvas.clientHeight;if(w<1||h<1)return;const dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);const left=60,right=w-12,top=22,bottom=h-37;
 const maxT=Math.max(mode==='pulley'?params.duration:10,Math.ceil(state.t/5)*5),maxY=history.reduce((max,s)=>Math.max(max,s.K,s.U,s.loss),1);const yMax=Math.ceil(maxY/Math.pow(10,Math.floor(Math.log10(maxY))))*Math.pow(10,Math.floor(Math.log10(maxY)));
 ctx.font='12px LabUI, Arial';ctx.fillStyle='#77776d';ctx.textAlign='left';ctx.fillText('Energía (J)',left,10);
 for(let i=0;i<=3;i++){const y=bottom-(bottom-top)*i/3;ctx.strokeStyle='#e7e5db';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(right,y);ctx.stroke();const value=yMax*i/3;ctx.textAlign='right';ctx.fillText(value>=1000?(value/1000).toFixed(value>=10000?0:1)+'k':fmt(value,0),left-8,y+3);}
 for(let i=0;i<=3;i++){const x=left+(right-left)*i/3;ctx.textAlign=i===0?'left':i===3?'right':'center';ctx.fillText(fmt(maxT*i/3,1),x,bottom+16);}
 ctx.textAlign='right';ctx.fillText('Tiempo (s)',right,h-3);
 const colors={K:'#548394',U:'#dba73e',loss:'#da714f'};ctx.save();ctx.beginPath();ctx.rect(left,top,right-left,bottom-top);ctx.clip();for(const key of ['K','U','loss']){ctx.beginPath();ctx.strokeStyle=colors[key];ctx.lineWidth=2;for(let i=0;i<history.length;i++){const s=history[i],x=left+s.t/maxT*(right-left),y=bottom-s[key]/yMax*(bottom-top);i===0?ctx.moveTo(x,y):ctx.lineTo(x,y);}ctx.stroke();const last=history.at(-1);if(last){ctx.beginPath();ctx.arc(left+last.t/maxT*(right-left),bottom-last[key]/yMax*(bottom-top),2.6,0,Math.PI*2);ctx.fillStyle=colors[key];ctx.fill();}}ctx.restore();
}
function notify(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{$('toast').hidden=true;},3200);}
function exportData(){sample(history.at(-1)?.t!==state.t);const keys=['t','x','h','v','K','U','loss','input','workNet','rope','power','energyError'];const headers=['tiempo_s','posicion_x_m','altura_m','velocidad_m_s','energia_cinetica_J','energia_potencial_J','energia_disipada_J','trabajo_aplicado_J','trabajo_neto_J','cuerda_m','potencia_W','diferencia_balance_J'];const content=[`# Experimento: ${configs[mode].name}`,`# Parametros: ${JSON.stringify(params)}`,'# g = 9.81 m/s^2',headers.join(','),...history.map(row=>keys.map(key=>Number(row[key]||0).toFixed(6)).join(','))].join('\r\n');const blob=new Blob(['\ufeff'+content],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`acme-${mode}-datos.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify(`Datos descargados: ${history.length} muestras.`);}
document.querySelectorAll('.scenario-tab').forEach(button=>button.addEventListener('click',()=>choose(button.dataset.mode)));
document.querySelector('.scenario-tabs').addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const buttons=[...document.querySelectorAll('.scenario-tab')],current=buttons.findIndex(b=>b.dataset.mode===mode);let next=event.key==='Home'?0:event.key==='End'?2:(current+(event.key==='ArrowRight'?1:2))%3;buttons[next].focus();choose(buttons[next].dataset.mode);});
$('play').addEventListener('click',()=>{if(state.finished)reset();playing=!playing;state.status=playing?(state.t===0?'Experimento en marcha':state.status):'Simulación pausada';updateUI();});$('restart').addEventListener('click',reset);$('speed').addEventListener('change',e=>{speed=Number(e.target.value);});$('export').addEventListener('click',exportData);$('export-top').addEventListener('click',exportData);
$('forces-toggle').addEventListener('click',()=>{scene.showForces=!scene.showForces;$('force-legend').hidden=!scene.showForces;$('forces-toggle').setAttribute('aria-pressed',String(scene.showForces));scene.update(state,params);});
$('defaults').addEventListener('click',()=>choose(mode));
$('zoom-in').addEventListener('click',()=>scene.zoom(.82));$('zoom-out').addEventListener('click',()=>scene.zoom(1.22));
function expandedFallback(){const expanded=$('experiment').classList.toggle('expanded-preview');$('expand').textContent=expanded?'Reducir ↙':'Ampliar ↗';$('experiment').scrollIntoView({block:'start',behavior:'smooth'});}
$('expand').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if($('experiment').requestFullscreen)await $('experiment').requestFullscreen();else expandedFallback();}catch{expandedFallback();}});
document.addEventListener('fullscreenchange',()=>{$('expand').textContent=document.fullscreenElement?'Reducir ↙':'Ampliar ↗';scene.resize();});
document.addEventListener('keydown',event=>{if(event.ctrlKey||event.metaKey||event.altKey||['INPUT','SELECT','TEXTAREA','BUTTON','SUMMARY'].includes(event.target.tagName))return;if(event.code==='Space'){event.preventDefault();$('play').click();}else if(event.key.toLowerCase()==='r')reset();});
document.querySelectorAll('[data-camera]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-camera]').forEach(b=>{const active=b===button;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});scene.setCamera(button.dataset.camera);scene.update(state,params);}));
new ResizeObserver(drawChart).observe($('chart'));document.fonts.ready.then(drawChart);document.addEventListener('visibilitychange',()=>{previous=performance.now();accumulator=0;});
function frame(now){const delta=Math.min(.06,(now-previous)/1000);previous=now;if(playing&&!document.hidden){if(mode==='pulley'&&approachTime<approachDuration){approachTime=Math.min(approachDuration,approachTime+delta*speed);state.status='El Coyote se acerca a la cuerda';scene.update(state,params,{approach:approachTime/approachDuration,motionTime:approachTime});}else{accumulator+=delta*speed;while(accumulator>=.008){state=advance(state,params,.008);accumulator-=.008;sample();if(state.finished){playing=false;sample(history.at(-1)?.t!==state.t);break;}}scene.update(state,params,{approach:1,motionTime:approachTime+state.t});}if(now-lastUI>70){lastUI=now;updateUI();drawChart();}if(!playing){updateUI();drawChart();}}scene.render();requestAnimationFrame(frame);}
choose('pulley');requestAnimationFrame(frame);
